entries[248340] = { ["name"] = "Fokus des astralen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+3.486 Intelligenz\n+5.458 Ausdauer\nErhöht Eure kritische Trefferwertung um + 266.\n+ 494 Vielseitigkeit\nSchließt den Erfolg \"Astrale Waffen der Eroberung\" ab, um zusätzliche Waffen kaufen zu können.\nVerkaufspreis:" }
entries[248341] = { ["name"] = "Streitkolben des astralen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n2,938 - 3,779 Schaden Geschwindigkeit 2.60\n(1,292 Schaden pro Sekunde)\n+1.136 Beweglichkeit\n+5.458 Ausdauer\nErhöht Eure kritische Trefferwertung um + 217.\n+ 543 Vielseitigkeit\nHaltbarkeit 110 / 110\nSchließt den Erfolg \"Astrale Waffen der Eroberung\" ab, um zusätzliche Waffen kaufen zu können.\nVerkaufspreis:" }
