entries[248761] = { ["name"] = "Bomber des Braufests", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dies ist ein Flugreittier.\nBeschwört einen Bomber des Braufests oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Passt auf, dass Ihr nicht die Munition verschlingt.\"\nBeute:\nCoren Düsterbräu\nFeiertag:\nBraufest" }
entries[248764] = { ["name"] = "Kunstfertige Teleportfalle", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Platziert eine Teleportfalle zu Euren Füßen. Der erste Gegner, der sich auf 2 Meter nähert, wird 10 Meter nach hinten teleportiert und 2 Sek. lang um 50% verlangsamt.\nDie Falle bleibt 1 Min. lang bestehen, bevor sie automatisch entschärft wird.\n\nKann nur in Tiefen und im Freien in Khaz Algar verwendet werden. (1 Min Abklingzeit)\nVerkaufspreis:" }
