entries[250104] = { ["name"] = "Nethermantel der Seelenbinderin", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[250105] = { ["name"] = "Haigeprüftes Spitzenhorn", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Spitzenhörner werden oft von den Pflanzen angezogen, die im Meer wachsen. Manche von ihnen haben sich dort gegen die gefährlichsten Bestien durchgesetzt, was sie zu wahren Kalu'ak macht.\"\nHandelsposten" }
entries[250106] = { ["name"] = "Schollenschreiterspitzenhorn", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese seltenen, im Azurblauen Gebirge einheimischen Kreaturen werden von den Tuskarr in der Region als gesegnet angesehen.\"\nHandelsposten" }
entries[250107] = { ["name"] = "Muttern und Bolzen", ["text"] = "\"Diverse, teilweise verdaute Teile zur Reparatur eines Energiepylonen.\"" }
entries[250108] = { ["name"] = "Felsschreiterspitzenhorn", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Tuskarr verirren sich nur selten auf den Hochberg, aber die Spitzenhörner kommen oft hinunter an die Küste, um im Küstengewässer nach seltenen Delikatessen zu suchen.\"\nHandelsposten" }
entries[250110] = { ["name"] = "Waffenständer der Volltrefferhütte", ["text"] = "3\nWaffenständer der Volltrefferhütte\nBehausungsdekoration\nWird an Kriegsmeute gebunden\nBenutzen: Fügt diese Dekoration zu Eurer Haustruhe hinzu." }
