entries[250191] = { ["name"] = "Zügel des gallgebundenen Ur'zul", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dies ist ein Flugreittier.\nBeschwört Euren Gallgebundenen Ur'zul oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:" }
entries[250192] = { ["name"] = "Zügel des geisterhaften Ur'zul", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dies ist ein Flugreittier.\nBeschwört Euren Geisterhaften Ur'zul oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\nVerkaufspreis:\n\"Der geisterhafte Ur'zul ist ein gefräßiger Dämon, der verdorbenes Fleisch und Knochen verschlingt, als würde er einen Salat essen.\"\nWeltereignis:\nWoW Remix: Legion" }
