entries[250411] = { ["name"] = "Ruhestein des Zeitläufers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n80 ( 80)" }
entries[250423] = { ["name"] = "Zügel des Schlackenbasilisken", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Schlackenbasilisken lebten ursprünglich tief unter der Erde und ernährten sich von Obsidian und Basalt. Sie wurden an die Oberfläche gezwungen, als die Legion sie aus ihrer Heimat verdrängte.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250424] = { ["name"] = "Zügel des Leysteinbasilisken", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser schmucke Basilisk wird oft wegen der magischen Eigenschaften seiner Organe gejagt. Glücklicherweise erlaubt ihm seine Verbindung zu den Leylinien, die Ankunft von Feinden vorherzusehen.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250425] = { ["name"] = "Zügel des Teufelsschieferbasilisken", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Teufelsschieferbasilisken waren auf den Verheerten Inseln häufig anzutreffen, bis sie wegen ihrer wertvollen Haut in großem Maßstab von Bergarbeitern gejagt wurden.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250426] = { ["name"] = "Zügel des Aquamarinbasilisken", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Obwohl ihr Name etwas anderes vermuten lässt, ernähren sich Aquamarinbasilisken von einer breiten Palette an Küstenkristallen und Meeresgestein.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250427] = { ["name"] = "Zügel des Seuchenpirschers der Illidari", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Dämonen ernähren sich von Seuchen und lieben den Verfall. Wer kam auf die Idee, auf ihnen zu reiten?\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250428] = { ["name"] = "Zügel des Schreckenspirschers der Illidari", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Trotz ihrer Vorliebe für Fleisch und ihrer unnatürlichen Fähigkeit, Angst zu riechen, werden diese niederen Dämonen von den Illidari unterworfen und als zahme Jagdgefährten verwendet.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250429] = { ["name"] = "Zügel des Hochlandurhorns", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das Fell eines Hochlandurhorns ist unglaublich dick. Es gibt keine historischen Belege dafür, dass ein Hochlandurhorn jemals auf eine Beleidigung reagiert hätte.\"\nWeltereignis:\nWoW Remix: Legion" }
