entries[250721] = { ["name"] = "Zügel des Verschneiten Hochbergadlers", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Herumliegende Federn eines verschneiten Adlers auf dem Hochberg gelten als Vorzeichen für wechselnde Winde und Temperaturstürze.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250722] = { ["name"] = "Astraler Stand", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Lasst einen astralen Marktstand vom Himmel herabfallen, der 15 Min. lang dableibt. Kann nur im Freien verwendet werden. (15 Min Abklingzeit)" }
entries[250723] = { ["name"] = "Zügel des Baumspitzenhochbergadlers", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der majestätische Adler ist ein Symbol für den Stolz der Hochbergstämme. Die Fähigkeit dieser gewaltigen Tiere, Tauren auf ihrem Rücken zu tragen, zeugt von der schieren Größe und Stärke der Kreaturen des Hochbergs.\"\nWeltereignis:\nWoW Remix: Legion" }
