entries[250727] = { ["name"] = "Zügel des Nachtbrunnenmanasäblers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten" }
entries[250728] = { ["name"] = "Zügel des Arkbeerenmanasäblers", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Ihr Name rührt von ihrer optischen Ähnlichkeit mit den leuchtenden Beeren her, aus denen Arkwein hergestellt wird. Diese stolzen Katzen haben einen scharfen Sinn für die Leylinien, auf denen sie wandeln.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250741] = { ["name"] = "Verwirrender Jeton des Kartells", ["text"] = "The War Within – Saison 3\nWird beim Aufheben gebunden\nEinzigartig (200)\n\"Nur neun pro Kunde. Mit Bedacht ausgeben!\"" }
entries[250745] = { ["name"] = "Zügel des Teufelsvernarbten Manarochens", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen teufelsvernarbten Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\n\"Die ledrige Haut dieses Manarochens trägt die Narben der Teufelsverderbnis und ist Zeugnis des harten Überlebenskampfes auf Argus. Er neigt noch mehr als üblich zu Aggressionsausbrüchen.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250746] = { ["name"] = "Zügel des Blutreißermanarochens", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen Blutreißermanarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\n\"Die Zerschmetterung von Argus machte diese Art von Manarochen blutrünstig. Nun ernähren sie sich vom verderbten Blut aller Kreaturen, die sie zwischen ihre zahlreichen Zähne bekommen können.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250747] = { ["name"] = "Zügel des Albinomanarochens", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen Albinomanarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\n\n\"Die Zerschmetterung von Argus ließ die Manarochen mutieren, um sich ihrer neuen Umgebung anzupassen. Manche von ihnen gaben die Pigmentierung ihrer Haut auf, um im Gegenzug ihre Sinne zu schärfen.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250748] = { ["name"] = "Zügel des Leuchtenden Manarochens", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen leuchtenden Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Manarochen können ein helles Leuchten ausstrahlen, um Beute anzulocken.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250751] = { ["name"] = "Zügel des Zwielichtrenners", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Um Fressfeinden zu entgehen, dämpft dieser Renner das Leuchten seines Horns, wenn er sich versteckt. Provoziert man ihn, stößt er hingegen blendende Lichtblitze aus.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250752] = { ["name"] = "Zügel des Goldenen Sonnenrenners", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Freigeist liebt lange Spaziergänge am Strand und tollt gerne auf bunten Blumenwiesen herum.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250756] = { ["name"] = "Zügel des Türkisrenners", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Benannt nach seinen einzigartig gefärbten Augen, die einem direkt in die Seele zu starren scheinen, zeigt der Türkisrenner mehr Intelligenz als seine Traumläufer-Artgenossen und ist bekannt dafür, den Charakter einer Person hervorragend einschätzen zu können.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250757] = { ["name"] = "Zügel des Düsternisalptraums", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Kreatur wurde vom Smaragdgrünen Alptraum berührt. Wenn sie einem im Traum erscheint, gilt das als Zeichen des Unglücks, und wer sie im wachen Zustand zu Gesicht bekommt, dem droht eine Katastrophe.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250758] = { ["name"] = "Zügel des Knochenrosses des Vergessens", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Ein gutes Schlachtross ist treu bis auf die Knochen. Dieses Pferd hat seine sterbliche Hülle abgelegt und ist ein Vorbote von Mangel und Tod.\"\nWeltereignis:\nWoW Remix: Legion" }
