entries[250802] = { ["name"] = "Zügel des langhörnigen Zobeltalbuks", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Die Talbuks von Argus haben langes, grobes Fell in leuchtenden Farben, die die vielen Schattierungen ihres zerbrochenen Planeten widerspiegeln.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250803] = { ["name"] = "Granatfarbener Ruinprescher", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Mit ihrer widerstandsfähigen Panzerung tragen die Ruinprescher von Argus ihre Reiter furchtlos über das zerklüftete Ödland des Planeten und darüber hinaus.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250804] = { ["name"] = "Langhörniger Karghuftalbuk", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Dieser teufelsdurchdrungene Talbuk trägt Narben von Jahrzehnten des Kampfes und ist damit das perfekte Reittier für unerschrockene Abenteurer.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250805] = { ["name"] = "Zügel des langhörnigen Argustalbuks", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Nur eine kleine Zahl von Talbuks hat es geschafft, von der Ausbeutung ihrer Heimatwelt durch die Legion unberührt zu bleiben. Diese Unbeugsamkeit macht sie zu wahrlich noblen Reittieren.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[250806] = { ["name"] = "Zügel des langhörnigen Berylltalbuks", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nMit der Veröffentlichung von \"Legion Remix: Ewiges Argus\" verfügbar.\nMit der Veröffentlichung von \"Legion Remix: Aufstieg der Nachtsüchtigen\" verfügbar.\n\n\"Dieser wilde Talbuk ist in den Ruinen von Argus heimisch und hat Jahrzehnte des Konflikts überlebt.\"\nWeltereignis:\nWoW Remix: Legion" }
