entries[250926] = { ["name"] = "Hochlandputer", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Wilde und besonders große Truthähne, die nach der Verschandelung von Tirisfal während des Vierten Krieges gelegentlich in dessen tiefen Wäldern zu sehen sind.\"\nHandelsposten" }
