entries[250928] = { ["name"] = "Mysteriöser Truthahn", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Es hat noch niemand versucht, aus diesem Reittier ein köstliches Mahl zu machen.\"\nHandelsposten" }
