entries[251999] = { ["name"] = "Fehlerhafter Teufelsfeuerkristall", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 1 zusätzlichen Rang von ' Ich bin meine Narben! '.\n\nIch bin meine Narben!\nAngreifer erleiden im Verlauf von 10 Sek. [((14% Angriffs-/Zaubermacht)) * 10 / 2] Chaosschaden durch Euer teufelsvernarbtes Fleisch.\n\nSchaden gegen mit ' Teufelsberührt ' belegte Gegner wird verdoppelt.\n\nDieser Effekt ist bis zu 5-mal stapelbar.\n80 ( 80)" }
