entries[252950] = { ["name"] = "Sternfunkelnder Netherdrache", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dies ist ein Flugreittier.\nBeschwört dieses Flugreittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nachdem er Euch bis ans Ende der Scherbenwelt und noch weiter getragen hat, fühlte sich der Netherschwingendrache am Ende auch zu den blauen Himmeln von Azeroth hingezogen.\"\nPromotion:\nBurning Crusade Classic" }
entries[252952] = { ["name"] = "Verzauberte Beeren", ["text"] = "Questgegenstand" }
entries[252954] = { ["name"] = "Teufelsgeweihte Zügel des Giftbrutbezwingers", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Todesritter können dieses Reittier benutzen.\nBeschwört Euren teufelsgeweihten Giftbrutbezwinger oder gibt ihn wieder frei. Dieses Reittier steht nur Todesrittern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese fliegende Vereinigung der Mächte des Todes und der Hölle zerfetzt die Lüfte mit ihrem schaurigen Kreischen.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[252990] = { ["name"] = "Süßigkeiten aus Drustvar", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schlotternächte" }
entries[253011] = { ["name"] = "Kampfgildenpunsch der brutalen Heilung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Stellt 25% Eurer maximalen Gesundheit wieder her. Kann nur in einer Arena der Kampfgilde verwendet werden. (5 Min Abklingzeit)" }
entries[253013] = { ["name"] = "Schlächterzügel des teufelsgeweihten Kreischers", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Dämonenjäger können dieses Reittier benutzen.\nBeschwört Euren teufelsgeweihten Kreischer des Schlächters oder gibt ihn wieder frei. Dieses Reittier steht nur Dämonenjägern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur die fähigsten Dämonenjäger können ihn aus dem Himmel reißen.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[253014] = { ["name"] = "Kampfgildentonikum der Stärke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Erhöht Eure Stärke 25 Sek. lang um 25%. Kann nur in einer Arena der Kampfgilde verwendet werden. (5 Min Abklingzeit)" }
