entries[253024] = { ["name"] = "Verachtungsschwingengötze des Teufelsdruiden", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Schaltet die Verachtungsschwinge als Fluggestalt beim Barbier frei. Diese Gestalt steht nur Druiden zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Schaltet die Option für die Verachtungsschwinge als Fluggestalt beim Barbier frei. Diese Gestalt steht nur Druiden zur Verfügung.\"" }
entries[253025] = { ["name"] = "Zügel des teufelsgeweihten Wolfsfalken", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Jäger können dieses Reittier benutzen.\nBeschwört Euren teufelsgeweihten Wolfsfalken oder gibt ihn wieder frei. Dieses Reittier steht nur Jägern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Gezeichnet durch den Krieg auf den Verheerten Inseln, verdient dieser Wolfsfalke ein gutes Zuhause.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[253026] = { ["name"] = "Teufelsgeweihte Scheibe des Erzmagiers", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Magier können dieses Reittier benutzen.\nBeschwört Eure teufelsgeweihte Scheibe des Erzmagiers oder gibt sie wieder frei. Dieses Reittier steht nur Magiern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einige Magier sagen, dämonische Magie sei \"instabil\" oder \"korrumpierend\" oder \"verboten\". Einige Magier liegen falsch.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[253027] = { ["name"] = "Teufelsgeweihte Glocke des Großmeisters", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Mönche können dieses Reittier benutzen.\nBeschwört Euren teufelsgeweihten Begleiter des Großmeisters oder gibt ihn wieder frei. Dieses Reittier steht nur Mönchen zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das verzerrte Antlitz eines geliebten Begleiters.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[253028] = { ["name"] = "Zügel des teufelsgeweihten Streitrosses des Hochlords", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Paladine können dieses Reittier benutzen.\nBeschwört Euer teufelsgeweihtes Streitross des Hochlords oder gibt es wieder frei. Dieses Reittier steht nur Paladinen zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses Pferd wurde auf ewig durch die verderbte Magie der Legion gezeichnet.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[253029] = { ["name"] = "Teufelsgeweihte Pfeife des Suchers", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Priester können dieses Reittier benutzen.\nBeschwört Euren teufelsgeweihten Sucher des Hohepriesters oder gibt ihn wieder frei. Dieses Reittier steht nur Priestern zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser dämonisch verderbte gefiederte Freund schlägt in einem frenetischen Tempo mit den Flügeln, um sich weit vom Getümmel am Boden abzuheben.\"\nWeltereignis:\nWoW Remix: Legion" }
entries[253030] = { ["name"] = "Zügel des teufelsgeweihten Omens der Schattenklinge", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Nur Schurken können dieses Reittier benutzen.\nBeschwört Euer teufelsgeweihtes Omen der Schattenklinge oder gibt es wieder frei. Dieses Reittier steht nur Schurken zur Verfügung.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Eure Feinde werden vor ihrem Ableben Angst spüren.\"\nWeltereignis:\nWoW Remix: Legion" }
