entries[253222] = { ["name"] = "Verderbter Dorn des Traums", ["text"] = "Legion Remix: Himmel in Flammen\nWird beim Aufheben gebunden\nBenutzen: Kombiniert 10 davon, um einen Gegenstand aus dem Smaragdgrünen Alptraum herzustellen.\n80 ( 80)\n\"Im Smaragdgrünen Alptraum kann sich selbst ein Dorn zu etwas Mächtigem und Tödlichem entwickeln.\"" }
entries[253223] = { ["name"] = "Fraktalteufelssplitter", ["text"] = "Legion Remix: Legionsrichter\nWird beim Aufheben gebunden\nBenutzen: Kombiniert 10 davon, um einen Gegenstand aus dem Grabmal des Sargeras herzustellen.\n80 ( 80)\n\"Die Macht des Betrügers ist so groß, dass selbst ein Tropfen seines Blutes, der erkaltet und zu einem Splitter kristallisiert, nahezu unendliches Potenzial enthält.\"" }
entries[253224] = { ["name"] = "Partikel der zerbrochenen Zeit", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nBenutzen: Kombiniert 10 davon, um einen Gegenstand herzustellen, der zu einem verfügbaren Schlachtzug in Legion Remix gehört.\n80 ( 80)\n\"Ein Prismasplitter, der mit dieser fragmentierten Zeitlinie in Resonanz steht. Zugleich nimmt er Gestalt an als verderbter Dorn, als Hexenmeisteredelstein, als teufelsleuchtender Splitter oder als Echo des Todes.\"" }
entries[253227] = { ["name"] = "Makelloser Zeitfaden", ["text"] = "Legion Remix: Echos der Ewigen\nWird beim Aufheben gebunden\nBenutzen: Kombiniert 10 davon, um einen Gegenstand von unfassbarem Potenzial zu erschaffen.\n80 ( 80)\n\"In einer nun kollabierenden alternativen Zeitlinie, in der der ewige Drachenschwarm mit der Geschichte der dritten Legionsinvasion experimentiert, werden unverderbte Momente zunehmend seltener und bergen eine phänomenale Macht.\"" }
